func (this *Test_org_eclipse_swt_widgets_Control) Test_ExceptionsThrownInDisposeListenerDontPreventDisposal() {
	this.disposedIntentionally = true
	var oldHandler func(error) = swt.DisplayGetCurrent().GetRuntimeExceptionHandler()
	{
		defer func() {
			swt.DisplayGetCurrent().SetRuntimeExceptionHandler(oldHandler)
		}()
		var handledExceptions *jrt.List = jrt.NewList()
		swt.DisplayGetCurrent().SetRuntimeExceptionHandler(func(exception error) {
			handledExceptions.Add(exception)
		})
		var listenerInvocations []int32 = make([]int32, 1)
		this.control.AddDisposeListener(&DisposeListenerFunc{fn: func(e *swt.DisposeEvent) {
			listenerInvocations[0]++
		}})
		this.control.AddDisposeListener(&DisposeListenerFunc{fn: func(e *swt.DisposeEvent) {
			panic(&jrt.RuntimeException{Message: "Test exception handling"})
		}})
		this.control.AddDisposeListener(&DisposeListenerFunc{fn: func(e *swt.DisposeEvent) {
			listenerInvocations[0]++
		}})
		func() {
			defer func() {
				r := recover()
				if r == nil {
					return
				}
				if e, ok := r.(error); ok {
					_ = e
					junit.Fail("The exception in the listener should have been logged, not passed along to the caller")
				} else {
					panic(r)
				}
			}()
			this.control.Dispose()
		}()
		junit.AssertTrue(this.control.IsDisposed())
		junit.AssertEquals(int32(2), int32(listenerInvocations[0]))
		junit.AssertEquals(int32(1), int32(handledExceptions.Size()))
	}
}

